    try {
      storedChecksum = JSON.parse(backup.entries[sourceChecksumKey]);
      user = JSON.parse(backup.entries[sourceIdKey]);
      if (Object.prototype.hasOwnProperty.call(backup.entries, sourceSettingsKey)) settings = JSON.parse(backup.entries[sourceSettingsKey]);
    } catch (_) { throw new Error('Backup is missing valid player or settings data.'); }
    if (typeof storedChecksum !== 'number' || checksum !== storedChecksum) throw new Error('Backup checksum does not match. The file may be damaged.');
